import json
from pathlib import Path
sets = {
'Spil': [('Snake','Saml mad og undgå din egen hale.'),('Pong','Spil bordtennis mod computeren.'),('Pac-Man-inspireret labyrint','Saml prikker og undgå fjender i en original labyrint.'),('Tetris-inspirerede blokke','Rotér faldende blokke og ryd linjer.'),('Memory','Find de matchende kort.'),('2048','Kombinér tal og nå 2048.'),('Minestryger','Find miner med hjælp fra tallene.'),('Breakout','Slå bolden mod en mur af blokke.'),('Sudoku','Løs et talpuslespil med hints.'),('Flappy Bird-inspireret flyvespil','Flyv mellem forhindringer.'),('Ordgæt','Gæt et dansk ord på seks forsøg.'),('Simon Says','Gentag en voksende sekvens af farver.')],
'Værktøjer': [('Pomodoro','Arbejd fokuseret i intervaller.'),('Farvevælger','Lav en palet og kopiér farvekoder.'),('Markdown-editor','Skriv tekst med live forhåndsvisning.'),('Enhedsomregner','Omregn længde, vægt og temperatur.'),('Adgangskodegenerator','Generér adgangskoder lokalt med Web Crypto.'),('Ugebudget','Fordel et beløb på ugens udgifter.'),('Vanetracker','Markér dagens vaner og se dine fremskridt.'),('Beslutningshjul','Lad et hjul vælge mellem dine muligheder.'),('Stopur','Tag tid og gem mellemtider.'),('Pakkeliste','Lav en tjekliste til din næste tur.'),('Tekstværktøj','Tæl ord og tegn og skift store og små bogstaver.'),('Intervaltræner','Sæt træning og pauser i en gentaget timer.')],
'Kreativt': [('Pixel-editor','Tegn pixelkunst og eksportér som PNG.'),('Generativ plakat','Lav geometriske plakater med et klik.'),('Trommemaskine','Byg et beat i en 16-trins sequencer.'),('Kalejdoskop','Tegn symmetriske mønstre med musen.'),('Partikellegeplads','Leg med partikler der følger din markør.'),('Gradient-generator','Bland farver og kopiér CSS.'),('ASCII-kunst','Lav tekstbaserede mønstre.'),('Fraktaltræ','Udforsk et træ med justérbare grene.'),('Tegneblok','Tegn med farver og gem dit billede.'),('Lydlandskab','Bland syntetiske naturlyde med Web Audio.'),('Typografiplakat','Eksperimentér med tekst, størrelse og afstand.'),('Livets spil','Udforsk cellulære mønstre med Conway’s Game of Life.')]
}
items=[]
for category, rows in sets.items():
 for title,desc in rows:
  items.append(dict(day=len(items)+2,title=title,category=category,description=desc,prompt=f'Lav en simpel webapp: {title}. {desc} Brug HTML, CSS og JavaScript uden eksterne biblioteker. Gør den responsiv, tilgængelig med tastatur og anvendelig med touch. Tilføj tydelig hjælp og en nulstil-knap. Gem eventuelle personlige data lokalt i browseren.'))
Path('backlog.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
